  function city(p,id){ let h=7; for(let i=0;i<id.length;i++) h=(h*31+id.charCodeAt(i))>>>0; const r=()=>{ h=(h*1664525+1013904223)>>>0; return h/4294967296; }; let far='', near='', signs=0;
    let x=-8; while(x<240){ const w=13+r()*15, ht=30+r()*58; far+=`<rect x="${n(x)}" y="${n(170-ht)}" width="${n(w)}" height="${n(ht)}" fill="${p.K1}"/>`; x+=w+r()*4; }
    x=-10; while(x<240){ const w=18+r()*20, ht=22+r()*84, y=170-ht; near+=`<rect x="${n(x)}" y="${n(y)}" width="${n(w)}" height="${n(ht)}" fill="#070a1a"/><rect x="${n(x)}" y="${n(y)}" width="${n(w)}" height="1.2" fill="${r()<0.5?p.C:p.A}" opacity=".7"/>`;
      for(let wy=y+6; wy<163; wy+=7.5) for(let wx=x+3.5; wx<x+w-4; wx+=5.5){ if(r()<0.26) near+=`<rect x="${n(wx)}" y="${n(wy)}" width="2.8" height="3.6" fill="${r()<0.68?p.C:p.A}" opacity="${n(0.3+r()*0.5)}"/>`; }
      if(signs<2&&ht>50&&r()<0.5){ signs++; near+=`<rect x="${n(x+2.5)}" y="${n(y+8+r()*14)}" width="${n(w-5)}" height="${n(7+r()*9)}" rx="1" fill="${signs===1?p.A:p.C}" opacity=".85" filter="url(#fGlow)"/>`; }
      x+=w+2+r()*10; }
    return `<g opacity=".5">${far}</g><g opacity=".8">${near}</g>`; }
