    // drains
    for(const [x,z] of [[-4.5,6.6],[4.5,-6.6],[13,9],[-13,-9]]){ g.fillStyle='#3b4252'; g.fillRect(x-0.5,z-0.3,1,0.6); g.fillStyle='#1b1f2b'; for(let i=0;i<5;i++) g.fillRect(x-0.42+i*0.18,z-0.24,0.09,0.48); }
    // wear
