    vertexShader:'uniform mat4 tm; varying vec4 vR; varying vec3 vW; void main(){ vR=tm*vec4(position,1.0); vec4 w=modelMatrix*vec4(position,1.0); vW=w.xyz; gl_Position=projectionMatrix*viewMatrix*w; }',
