  const ph=1.95*Math.pow(cf.sz||1,0.85); const pivot=cf.pos.clone().add(V3(0,ph,0)); if(cf.visY!==undefined&&cf.onGround) pivot.y=cf.visY+ph; const dir=cf.aimDir(); const right=V3(Math.cos(cf.yaw),0,-Math.sin(cf.yaw));
